// Full locale overlay packs (./packs/{lang}.{section}.json) — deep translations beyond EN/FR stubs.
applySectionPacks({
  commonPageTranslations,
  matchFlowTranslations,
  competitionFlowTranslations,
  tournamentDetailTranslations,
});
for (const lang of Object.keys(commonPageTranslations)) {
  if (!localized[lang]) continue;
  localized[lang].commonPages = commonPageTranslations[lang];
  if (matchFlowTranslations[lang]) localized[lang].matchFlow = matchFlowTranslations[lang];
  if (competitionFlowTranslations[lang]) localized[lang].competitionFlow = competitionFlowTranslations[lang];
  if (tournamentDetailTranslations[lang]) localized[lang].tournamentDetail = tournamentDetailTranslations[lang];
}
applySettingsPacks(localized);

